# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM\'DA İMANLA İLGİLİ KAVRAMLAR VE YARATILIŞIN GAYESİ</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">AKİDE, İMAN, İSLAM VE İHSAN</text>\n  <text x="38" y="90" font-size="11.5" fill="#1e3a8a">• Akide (İtikat): Gönülden bağlanılan, düğüm gibi</text>\n  <text x="46" y="106" font-size="11" fill="#1e3a8a">sağlam inanç esasları bütünü.</text>\n  <text x="38" y="128" font-size="11.5" fill="#1e3a8a">• İman &amp; Mümin: Allah\'ın varlığını, birliğini (Tevhid)</text>\n  <text x="46" y="144" font-size="11" fill="#1e3a8a">ve Peygamber\'in getirdiklerini kalben tasdik, dille ikrar.</text>\n  <text x="38" y="166" font-size="11.5" fill="#1e3a8a">• İslam &amp; Müslüman: Allah\'a teslimiyet ve itaat.</text>\n  <text x="38" y="188" font-size="11.5" font-weight="bold" fill="#1d4ed8">• İhsan &amp; Muhsin: Allah\'ı görüyormuşçasına</text>\n  <text x="46" y="204" font-size="11" fill="#1d4ed8">bilinçli kulluk yapmak; her işi en güzel şekilde yapmak.</text>\n  <text x="38" y="224" font-size="11" fill="#3b82f6">• İhlas: İbadet ve iyilikleri yalnız Allah rızası için yapmak.</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9f1239">İNANÇ AÇISINDAN ZIT KAVRAMLAR</text>\n  <text x="370" y="92" font-size="11.5" font-weight="bold" fill="#881337">• Tevhid ↔ Şirk (Müşrik):</text>\n  <text x="378" y="108" font-size="11" fill="#9f1239">Allah\'ı birlemek (Tevhid) ↔ Allah\'a ortak koşmak (Şirk).</text>\n  <text x="370" y="132" font-size="11.5" font-weight="bold" fill="#881337">• İman ↔ Küfür (Kâfir / İnkâr):</text>\n  <text x="378" y="148" font-size="11" fill="#9f1239">Hakikati tasdik etmek ↔ Dinin esaslarını bilerek reddetmek.</text>\n  <text x="370" y="172" font-size="11.5" font-weight="bold" fill="#881337">• İhlas ↔ Nifak (Münafık) &amp; Riya:</text>\n  <text x="378" y="188" font-size="11" fill="#9f1239">Kalben inanmadığı hâlde dille inandığını söylemek (Nifak).</text>\n  <text x="370" y="212" font-size="11.5" font-weight="bold" fill="#881337">• Hidayet (Doğru yol) ↔ Dalalet (Sapıklık) | Takva ↔ Fısk</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TOPLUMUN TEMELİ AİLE: İSLAM\'DA AİLE KURUMU VE NİKÂH</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">KUR\'AN\'DA AİLENİN ÜÇ TEMEL DAYANAĞI</text>\n  <text x="182" y="83" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">(Rûm Suresi, 21. Ayet)</text>\n  <rect x="42" y="94" width="280" height="38" rx="6" fill="#ffffff" stroke="#86efac"/>\n  <text x="52" y="117" font-size="11.5" font-weight="bold" fill="#14532d">1. Sekînet (Litaskünû): Huzur, güven ve sükûnet</text>\n  <rect x="42" y="140" width="280" height="38" rx="6" fill="#ffffff" stroke="#86efac"/>\n  <text x="52" y="163" font-size="11.5" font-weight="bold" fill="#14532d">2. Meveddet: Karşılıklı derin sevgi ve muhabbet</text>\n  <rect x="42" y="186" width="280" height="38" rx="6" fill="#ffffff" stroke="#86efac"/>\n  <text x="52" y="209" font-size="11.5" font-weight="bold" fill="#14532d">3. Rahmet: Şefkat, merhamet, anlayış ve bağışlama</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">NİKÂH AKDİ VE UNSURLARI</text>\n  <text x="370" y="92" font-size="11.5" fill="#78350f">• Nikâh: Aralarında evlenme engeli bulunmayan kadın</text>\n  <text x="378" y="108" font-size="11" fill="#78350f">ve erkeğin şahitler huzurunda irade beyanıyla (îcap-kabul)</text>\n  <text x="378" y="124" font-size="11" fill="#78350f">yaptıkları kutsal evlilik sözleşmesidir (Mîsâkan galîzâ).</text>\n  <text x="370" y="148" font-size="11.5" font-weight="bold" fill="#92400e">• Geçerlilik Şartları:</text>\n  <text x="378" y="166" font-size="11" fill="#78350f">- Eşlerin özgür iradesi ve rızası (zorla nikâh olmaz)</text>\n  <text x="378" y="182" font-size="11" fill="#78350f">- Şahitlerin bulunması ve evliliğin topluma ilan edilmesi (aleni)</text>\n  <text x="378" y="198" font-size="11" fill="#78350f">- Mehir: Erkeğin eşine güvence ve hediye olarak verdiği mal/para.</text>\n  <text x="370" y="220" font-size="11" font-weight="bold" fill="#b45309">• Amaç: Neslin, iffetin ve toplumsal ahlakın korunması.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" xmlns="http://www.w3.org/2000/svg" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AİLE BİREYLERİNİN KARŞILIKLI HAK VE SORUMLULUKLARI</text>\n  <rect x="20" y="42" width="210" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="125" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">EŞLERİN BİRBİRİNE KARŞI</text>\n  <text x="32" y="92" font-size="11" fill="#581c87">• Sadakat, iffet ve mahremiyeti</text>\n  <text x="38" y="108" font-size="11" fill="#581c87">(aile sırlarını) korumak.</text>\n  <text x="32" y="130" font-size="11" fill="#581c87">• Güzel geçinmek (muâşeret-i</text>\n  <text x="38" y="146" font-size="11" fill="#581c87">cemîle), nezaket ve sabır.</text>\n  <text x="32" y="168" font-size="11" fill="#581c87">• Kararları istişare (danışma) ve</text>\n  <text x="38" y="184" font-size="11" fill="#581c87">ortak sorumlulukla almak.</text>\n  <text x="32" y="206" font-size="10.5" font-weight="bold" fill="#7e22ce">"Sizin en hayırlınız ailesine karşı</text>\n  <text x="32" y="220" font-size="10.5" font-weight="bold" fill="#7e22ce">en hayırlı olanınızdır." (Hadis)</text>\n  <rect x="245" y="42" width="210" height="200" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="350" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">ANNE-BABANIN ÇOCUĞA KARŞI</text>\n  <text x="257" y="92" font-size="11" fill="#7c2d12">• Çocuğa güzel ve anlamlı bir</text>\n  <text x="263" y="108" font-size="11" fill="#7c2d12">isim koymak.</text>\n  <text x="257" y="130" font-size="11" fill="#7c2d12">• Helal rızıkla beslemek ve</text>\n  <text x="263" y="146" font-size="11" fill="#7c2d12">sağlıklı büyümesini sağlamak.</text>\n  <text x="257" y="168" font-size="11" fill="#7c2d12">• Güzel ahlak, iman ve ilim</text>\n  <text x="263" y="184" font-size="11" fill="#7c2d12">terbiyesi (eğitimi) vermek.</text>\n  <text x="257" y="206" font-size="11" font-weight="bold" fill="#c2410c">• Çocuklar arasında sevgi ve</text>\n  <text x="263" y="222" font-size="11" font-weight="bold" fill="#c2410c">hediyede ADALETLİ davranmak.</text>\n  <rect x="470" y="42" width="210" height="200" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="575" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">ÇOCUĞUN ANNE-BABAYA VE</text>\n  <text x="575" y="81" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">AKRABAYA KARŞI (SILA-İ RAHİM)</text>\n  <text x="482" y="104" font-size="11" fill="#164e63">• Anne-babaya iyilik ve ihsan</text>\n  <text x="488" y="120" font-size="11" fill="#164e63">(Birr-u vâlideyn); \'öf\' bile dememek</text>\n  <text x="488" y="136" font-size="11" fill="#164e63">(İsrâ suresi, 23-24. ayetler).</text>\n  <text x="482" y="158" font-size="11" fill="#164e63">• Yaşlandıklarında onlara şefkat</text>\n  <text x="488" y="174" font-size="11" fill="#164e63">kanatlarını germek ve dua etmek.</text>\n  <text x="482" y="198" font-size="11" font-weight="bold" fill="#0e7490">• Sıla-i Rahim: Akraba bağlarını</text>\n  <text x="488" y="214" font-size="11" font-weight="bold" fill="#0e7490">korumak, ziyaret ve yardımlaşmak.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
